import{_ as a,o as t,c as o,a7 as r}from"./chunks/framework.FWlv_suP.js";const u=JSON.parse('{"title":"Card Nest Data Collection","description":"Standalone summary of Card Nest data practices.","frontmatter":{"title":"Card Nest Data Collection","description":"Standalone summary of Card Nest data practices.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/card-nest.md","filePath":"data-collection/card-nest.md"}'),s={name:"data-collection/card-nest.md"};function i(n,e,l,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="card-nest-data-collection" tabindex="-1">Card Nest Data Collection <a class="header-anchor" href="#card-nest-data-collection" aria-label="Permalink to &quot;Card Nest Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> October 22, 2026</p><h2 id="data-stored-locally" tabindex="-1">Data stored locally <a class="header-anchor" href="#data-stored-locally" aria-label="Permalink to &quot;Data stored locally&quot;">​</a></h2><p>Card Nest stores card information, optional encrypted full card numbers and CVVs, transactions, receipts, income, budgets, categories, payment sources, balances, loans, EMIs, reminders, profile details, preferences, and report data in local SQLite storage.</p><p>The application PIN is stored only as a salted PBKDF2 hash. Android handles biometric verification without providing biometric templates to Card Nest.</p><h2 id="data-collected-by-the-developer" tabindex="-1">Data collected by the developer <a class="header-anchor" href="#data-collected-by-the-developer" aria-label="Permalink to &quot;Data collected by the developer&quot;">​</a></h2><p>Card Nest has no account, developer cloud, analytics, advertising, crash reporting, or tracking service. The developer does not receive app database contents, financial records, receipts, PINs, or usage data.</p><p>If you email support, the developer receives only the information you choose to include in that message.</p><h2 id="data-processed-outside-local-sqlite" tabindex="-1">Data processed outside local SQLite <a class="header-anchor" href="#data-processed-outside-local-sqlite" aria-label="Permalink to &quot;Data processed outside local SQLite&quot;">​</a></h2><ul><li>Android can store masked reminder content containing a card nickname, last digits, amount, and date when notifications are enabled.</li><li>Google may receive normal connection metadata when Google Fonts resources are requested.</li><li>A file or sharing provider you choose receives encrypted backups or readable report exports sent to it.</li><li>The camera and system photo picker provide receipt images only after your action and permission or selection.</li></ul><h2 id="optional-android-sms-review-data" tabindex="-1">Optional Android SMS Review data <a class="header-anchor" href="#optional-android-sms-review-data" aria-label="Permalink to &quot;Optional Android SMS Review data&quot;">​</a></h2><p>If you deliberately enable SMS Sync, Card Nest uses <code>READ_SMS</code> to examine the SMS inbox within the history range you select and <code>RECEIVE_SMS</code> to schedule processing after a new message arrives. It uses these permissions only to find financial transaction alerts and create review suggestions. It does not send SMS, access call logs or contacts, use SMS for advertising or analytics, or automatically add a transaction or make a payment.</p><p>Processing is on-device. The separate SMS Sync queue stores an encrypted extracted review record and a deduplication identity using an Android Keystore-backed AES-GCM key. Raw SMS bodies, senders, OTPs, and marketing messages are not retained in that queue. The developer does not receive SMS contents or data derived from them. You must explicitly approve any suggestion before it becomes a financial record.</p><p>You can turn SMS Sync off to stop future discovery and scheduling, revoke the permission in Android settings, or use <strong>Delete all data</strong> to clear SMS Sync settings and its encrypted queue. You can also paste a financial SMS for local parsing without granting inbox access.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Camera, selected photos, notifications, biometrics, file access, internet, and optional SMS permissions are used only for their corresponding features. Card Nest does not require location, contacts, phone, call-log, or broad gallery access. SMS permissions are restricted by Google Play and are available only where the app&#39;s distribution eligibility and required Play Console declaration or approval permit them.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',18)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
